// src/utils/topologyMapper.js

const edgeDefaults = {
  animated: true,
  style: { stroke: '#4A5B6E', strokeWidth: 2 },
  labelStyle: { fill: '#A0AEC0', fontWeight: 500, fontSize: '11px' },
  labelShowBg: true,
  labelBgStyle: { fill: '#23303D', stroke: '#4A5B6E' },
  labelBgPadding: [4, 4],
};

/**
 * Process ONT serial search through 4 JSON files with FULL connectivity chain
 * Path: ONT → OLT → Mandal Router → GP Ring
 */
export function processOntSearch(ontSerialNo, file1, file2, file3, file4) {
  // ── STEP 1: Find ONT in File 1 (ONT2OLT) ───────────────────────────────────
  const ontEntry = file1.find(ont => 
    ont.ont_serial_no?.trim().toLowerCase() === ontSerialNo?.trim().toLowerCase()
  );
  if (!ontEntry) return null;
  
  const { ont_serial_no, ont_id, olt_hostname, olt_ip_address } = ontEntry;
  if (!olt_hostname) return null;
  
  // ── STEP 2: Filter File 2 (OLT2Router) by olt_hostname ─────────────────────
  const oltEntries = file2.filter(entry => 
    entry.olt_hostname?.toLowerCase() === olt_hostname.toLowerCase()
  );
  
  // Get unique non-empty mandal routers
  const mandalRouters = [...new Set(
    oltEntries
      .map(e => e.mandal_router_hostname)
      .filter(h => h && h.trim() !== '')
  )];
  
  if (mandalRouters.length === 0) return null;
  const primaryMandalRouter = mandalRouters[0];
  
  // Get OLT entry details for node creation
  const primaryOltEntry = oltEntries[0];
  
  // ── STEP 3: Filter File 3 (child2parent) by mandal_router_hostname ─────────
  const file3Filtered = file3.filter(entry => 
    mandalRouters.includes(entry.mandal_router_hostname)
  );
  
  // Get unique topology values (deduplicated)
  const uniqueTopologies = [...new Set(
    file3Filtered.map(e => e.topology).filter(t => t && t.trim() !== '')
  )];
  
  if (uniqueTopologies.length === 0) return null;
  
  // ── STEP 4: Filter File 4 (GPtopology) by gp_ring_name ─────────────────────
  const ringData = file4.filter(entry => 
    uniqueTopologies.includes(entry.gp_ring_name)
  );
  
  if (ringData.length === 0) return null;
  
  // ── BUILD COMPLETE TOPOLOGY WITH FULL CONNECTIVITY ─────────────────────────
  return buildFullTopologyChain({
    ont: { serial: ont_serial_no, id: ont_id, hostname: `ONT-${ont_serial_no.slice(-6)}` },
    olt: { hostname: olt_hostname, ip: olt_ip_address },
    mandalRouter: { 
      hostname: primaryMandalRouter, 
      ip: primaryOltEntry?.mandal_router_ip 
    },
    ringData,
    uniqueTopologies
  });
}

/**
 * Build complete topology: ONT → OLT → Mandal Router → GP Ring
 */
export function buildFullTopologyChain({ ont, olt, mandalRouter, ringData, uniqueTopologies }) {
  const nodes = [];
  const edges = [];
  
  // Layout constants
  const startX = 50, midX = 300, ringCenterX = 600, ringCenterY = 260, ringRadius = 180;
  
  // ── 1. Create ONT Node (leftmost) ──────────────────────────────────────────
  const ontId = `ont-${ont.serial}`;
  nodes.push({
    id: ontId,
    type: 'fiberDevice',
    position: { x: startX, y: ringCenterY - 30 },
    data: { 
      type: 'ont', 
      hostname: ont.hostname, 
      ip: '', 
      serial: ont.serial,
      ontId: ont.id,
      isSearchOrigin: true
    },
    style: { border: '2px solid #22c55e', boxShadow: '0 0 10px rgba(34,197,94,0.4)' }
  });
  
  // ── 2. Create OLT Node ─────────────────────────────────────────────────────
  const oltId = `olt-${olt.hostname}`;
  nodes.push({
    id: oltId,
    type: 'fiberDevice',
    position: { x: midX - 100, y: ringCenterY - 30 },
    data: { 
      type: 'olt', 
      hostname: olt.hostname, 
      ip: olt.ip,
      connectedOnt: ont.serial
    }
  });
  
  // Edge: ONT → OLT
  edges.push({
    id: `edge-ont-olt-${ont.serial}`,
    source: ontId,
    target: oltId,
    label: 'GPON',
    ...edgeDefaults,
    style: { ...edgeDefaults.style, stroke: '#22c55e' }
  });
  
  // ── 3. Create Mandal Router Node (center of ring) ──────────────────────────
  const mandalId = `mandal-${mandalRouter.hostname}`;
  nodes.push({
    id: mandalId,
    type: 'fiberDevice',
    position: { x: ringCenterX - 60, y: ringCenterY - 30 },
    data: { 
      type: 'router', 
      hostname: mandalRouter.hostname, 
      ip: mandalRouter.ip,
      isCentral: true,
      connectedOlt: olt.hostname,
      topology: uniqueTopologies.join(', ')
    },
    style: { border: '3px solid #63b3ed', boxShadow: '0 0 15px rgba(99,179,237,0.6)' }
  });
  
  // Edge: OLT → Mandal Router
  edges.push({
    id: `edge-olt-mandal-${olt.hostname}`,
    source: oltId,
    target: mandalId,
    label: '10G Uplink',
    ...edgeDefaults
  });
  
  // ── 4. Collect & Create GP Router Nodes from ringData ──────────────────────
  const gpRouterMap = new Map(); // hostname → node data
  
  ringData.forEach(edge => {
    // A-end device (skip if it's the mandal router - already created)
    if (edge.a_end_device !== mandalRouter.hostname && !gpRouterMap.has(edge.a_end_device)) {
      gpRouterMap.set(edge.a_end_device, {
        hostname: edge.a_end_device,
        ip: edge.a_end_device_ip,
        interface: edge.a_end_device_interface,
        ringName: edge.gp_ring_name
      });
    }
    // B-end device
    if (edge.b_end_device !== mandalRouter.hostname && !gpRouterMap.has(edge.b_end_device)) {
      gpRouterMap.set(edge.b_end_device, {
        hostname: edge.b_end_device,
        ip: edge.b_end_device_ip,
        interface: edge.b_end_device_interface,
        ringName: edge.gp_ring_name
      });
    }
  });
  
  // Position GP routers in a ring around Mandal Router
  const gpRouters = Array.from(gpRouterMap.entries());
  const totalGp = gpRouters.length;
  
  gpRouters.forEach(([hostname, data], i) => {
    const angleDeg = (360 / Math.max(totalGp, 1)) * i;
    const angleRad = (angleDeg * Math.PI) / 180;
    const nodeId = `gp-${hostname}`;
    
    nodes.push({
      id: nodeId,
      type: 'fiberDevice',
      position: {
        x: ringCenterX + ringRadius * Math.cos(angleRad) - 60,
        y: ringCenterY + ringRadius * Math.sin(angleRad) - 30,
      },
      data: {
        type: 'router',
        hostname: data.hostname,
        ip: data.ip,
        interface: data.interface,
        ringName: data.ringName,
        isGpRouter: true
      }
    });
  });
  
  // ── 5. Create Ring Edges from ringData ─────────────────────────────────────
  ringData.forEach((edge, idx) => {
    const getSourceId = (device) => {
      if (device === mandalRouter.hostname) return mandalId;
      return `gp-${device}`;
    };
    
    edges.push({
      id: `ring-edge-${idx}-${edge.gp_ring_name}`,
      source: getSourceId(edge.a_end_device),
      target: getSourceId(edge.b_end_device),
      label: edge.linear_ring || 'Ring',
      ...edgeDefaults,
      style: { ...edgeDefaults.style, stroke: '#8b5cf6' }
    });
  });
  
  // ── 6. Connect Mandal Router to first GP router in each unique ring ────────
  // (Ensures central router connects to ring if not already connected via ringData)
  uniqueTopologies.forEach(topologyName => {
    const firstGpInRing = gpRouters.find(([_, data]) => data.ringName === topologyName);
    if (firstGpInRing) {
      const gpNodeId = `gp-${firstGpInRing[0]}`;
      // Only add if edge doesn't already exist
      const edgeExists = edges.some(e => 
        (e.source === mandalId && e.target === gpNodeId) ||
        (e.source === gpNodeId && e.target === mandalId)
      );
      if (!edgeExists) {
        edges.push({
          id: `mandal-gp-${topologyName}`,
          source: mandalId,
          target: gpNodeId,
          label: topologyName,
          ...edgeDefaults,
          style: { ...edgeDefaults.style, stroke: '#f59e0b', strokeDasharray: '5,5' }
        });
      }
    }
  });
  
  return { nodes, edges };
}

/**
 * Static ring builder for manual router drill-down (preserves original behavior)
 */
export function buildStaticRingTopology(clickedNode, siblings = []) {
  const defaultSiblings = [
    { id: `${clickedNode.id}-peer1`, hostname: 'peer-router-01', ip: '10.0.0.1' },
    { id: `${clickedNode.id}-peer2`, hostname: 'peer-router-02', ip: '10.0.0.2' },
    { id: `${clickedNode.id}-peer3`, hostname: 'peer-router-03', ip: '10.0.0.3' },
    { id: `${clickedNode.id}-peer4`, hostname: 'peer-router-04', ip: '10.0.0.4' },
  ];
  
  const allNodes = [clickedNode, ...(siblings.length ? siblings : defaultSiblings).map(s => ({
    id: s.id,
    type: 'fiberDevice',
    data: { type: 'router', hostname: s.hostname, ip: s.ip },
    position: { x: 0, y: 0 }
  }))];
  
  const cx = 400, cy = 260, radius = 200;
  const total = allNodes.length;
  
  const ringNodes = allNodes.map((node, i) => {
    const angleDeg = (360 / total) * i - 90;
    const angleRad = (angleDeg * Math.PI) / 180;
    return {
      ...node,
      position: {
        x: cx + radius * Math.cos(angleRad) - 60,
        y: cy + radius * Math.sin(angleRad) - 30,
      },
      style: node.id === clickedNode.id
        ? { border: '2px solid #63b3ed', boxShadow: '0 0 12px rgba(99,179,237,0.5)' }
        : {}
    };
  });
  
  const ringEdges = ringNodes.map((node, i) => {
    const next = ringNodes[(i + 1) % ringNodes.length];
    return {
      id: `ring-edge-${i}`,
      source: node.id,
      target: next.id,
      label: '10G Ring',
      ...edgeDefaults
    };
  });
  
  return { ringNodes, ringEdges };
}
